  return String(attempt)
}

export function nodeTiming(_timeline: Timeline, _nodeId: string, _attempt: number | null, _result?: WorkerResult | null): Timing | null {
  return null
}

export function attemptStrip(_detail: RunDetail, _timeline: Timeline, _nodeId: string): StripItem[] {
  return []
}

