  const detail = runDetail(RUN_THIRD_ATTEMPT, 'running', DEFINITION, CREATED_AT, UPDATED_AT, {
    launch_ui: { status: 'succeeded', attempt: 1, session: UI_SESSION, result: 'ui' },
    handoff: { status: 'succeeded', attempt: 1 },
