/* ---- Launch node sections (docs/PRD_VIEWER_UX.md 4.5) ---- */

.worker-verified { margin: 0 0 8px; font-size: 0.9rem; }
EOF
cat > src/projects/node/verify.css <<'EOF'
/* ---- Verification and candidate sections (docs/PRD_VIEWER_UX.md 4.6) ---- */

.worker-report-link { margin: 0; font-size: 0.85rem; color: var(--text-muted); }
.lane-result .worker-report-link { margin-bottom: 8px; }
EOF
cat > src/projects/node/review.css <<'EOF'
/* ---- Review section (docs/PRD_VIEWER_UX.md 4.7); the review panel's own rules stay in App.css until S4c moves them. ---- */

.node-section .review-result { margin-top: 0; }
EOF
cat > src/projects/node/controller.css <<'EOF'
/* ---- The controller's steps: handoff, approval, integrate (docs/PRD_VIEWER_UX.md 4.9): one panel, no index ---- */

.controller-panel { margin-top: 8px; }
EOF
